#!/usr/bin/env python3
"""Turn `g++ -MM` output into a DOT graph and a CSV edge list.

The compiler already reports which header each translation unit includes, so
this only reformats that — no second parser, and nothing to keep in sync.

Usage:  deps_to_dot.py <output-dir>
Reads <output-dir>/cpp_deps.makefile, writes cpp_deps.dot/.csv/.svg there.
"""

import csv
import os
import subprocess
import sys

# Headers generated by bison/flex, attributed to the source they come from.
GENERATED = {"icl_parser.hh": "src/icl/icl_parser.yy", "icl_lexer.hh": "src/icl/icl_lexer.l"}

SHARED = [
    "src/icl/icl_parser.yy", "src/icl/icl_lexer.l", "src/icl/icl_ast.h", "src/icl/icl_driver.h",
    "src/icl/icl_driver.cc", "src/icl/format_tree.h", "src/icl/format_tree.cc", "src/icl/format_job.h",
    "src/icl/format_job.cc",
]


def main():
    out_dir = sys.argv[1] if len(sys.argv) > 1 else "."
    mk = os.path.join(out_dir, "cpp_deps.makefile")
    with open(mk) as handle:
        raw = handle.read()

    edges = {}
    for line in raw.replace("\\\n", " ").split("\n"):
        if ":" not in line:
            continue
        target, deps = line.split(":", 1)
        target = os.path.basename(target.strip())
        if not target.endswith(".o"):
            continue
        dependencies = deps.split()
        source = next((dep for dep in dependencies
                       if dep.startswith("src/") and dep.endswith(".cc")), None)
        if source is None:
            continue
        found = set()
        for dep in dependencies:
            dep = GENERATED.get(os.path.basename(dep), dep)
            if dep.startswith("src/") and os.path.isfile(dep):
                found.add(dep)
        found.discard(source)
        edges[source] = found

    rows = sorted((s, d) for s in edges for d in edges[s])

    dot = ["digraph icl_format {", "  rankdir=LR;",
           '  node [shape=box fontname="sans-serif"];',
           "  subgraph cluster_shared {",
           '    label="shared: AST -> layout -> job"; style=dashed;']
    known = set(edges) | {d for v in edges.values() for d in v}
    for name in SHARED:
        if name in known:
            dot.append('    "%s";' % name)
    dot.append("  }")
    for name in ("src/icl/icl_format_main.cc", "src/icl/icl_lsp_main.cc"):
        dot.append('  "%s" [style=filled fillcolor="#e8f0fe"];' % name)
    dot.append('  "src/utility/json.h" [style=filled fillcolor="#f0f0f0"];')
    dot += ['  "%s" -> "%s";' % (a, b) for a, b in rows]
    dot.append("}")
    with open(os.path.join(out_dir, "cpp_deps.dot"), "w") as handle:
        handle.write("\n".join(dot) + "\n")

    with open(os.path.join(out_dir, "cpp_deps.csv"), "w", newline="") as handle:
        writer = csv.writer(handle)
        writer.writerow(["source", "depends_on"])
        writer.writerows(rows)

    svg = os.path.join(out_dir, "cpp_deps.svg")
    if subprocess.run(["dot", "-Tsvg", os.path.join(out_dir, "cpp_deps.dot"),
                       "-o", svg], capture_output=True).returncode != 0:
        print("note: graphviz not installed; DOT and CSV written, no SVG")
    print("wrote %d edges over %d nodes" % (len(rows), len(known)))


if __name__ == "__main__":
    main()
